head.script:
scwin.onpageload = function() {

};
scwin.inputFormatter = function(val1, val2) {
    console.log('inputFormatter1', arguments);
    console.log('inputFormatter2', scwin.numberWithComma(val1));

    return val1.replaceAll(",", "");
}
scwin.inputUnformatter = function(val1, val2) {
    console.log('inputUnformatter1', arguments);
    console.log('inputUnformatter2', val1.replaceAll(",", ""));

    return scwin.numberWithComma(val1);
}
scwin.numberWithComma = function(x) {
    return x.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
};


	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_8').value == '1,111';
	}		
	scwin.unitTest = function(){
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
